	private void showWebhook(String url)
	{
		setupPanel.setVisible(true);
		if (url != null && !url.isEmpty())
		{
			webhookUrl.setText(url);
			webhookUrl.setCaretPosition(0);
			copyWebhook.setText("Copy Dink webhook");
		}
